//  VAR Result =       MAX(0, MIN(12, MonthsWorked))

//  RETURN IF(Result <> 0, Result)
// )

SUMX(
    VALUES('Fryst Fte'[ANST_NR]),
    VAR YearSelected = YEAR(MAX(Kalender[Datum]))
    VAR YearStart = DATE(YearSelected, 1, 1)
    VAR YearEnd = DATE(YearSelected, 12, 31)

    VAR StartDateRaw = MAX('Fryst FTE'[Anställningsdatum])
    VAR EndDateRaw = COALESCE(MAX('Fryst FTE'[Avgångsdatum]), YearEnd)

    VAR StartDate = MAX(StartDateRaw, YearStart)
    VAR EndDate = MIN(EndDateRaw, YearEnd)

    VAR Months = GENERATESERIES(1, 12)

    VAR Result =
        SUMX(
            Months,
            VAR MonthNum = [Value]
            VAR MonthStart = DATE(YearSelected, MonthNum, 1)
            VAR MonthEnd = EOMONTH(MonthStart, 0)
            VAR DaysInMonth = DAY(MonthEnd)

            VAR OverlapStart = MAX(StartDate, MonthStart)
            VAR OverlapEnd = MIN(EndDate, MonthEnd)

            VAR OverlapDays = DATEDIFF(OverlapStart, OverlapEnd, DAY) + 1

            VAR IsOverlap = OverlapEnd >= OverlapStart

            RETURN IF(IsOverlap, DIVIDE(OverlapDays, DaysInMonth), 0)
        )

    RETURN Result
)


